"""The bare numeric constants of the package, each with its reason.

``tests/unit/test_numeric_constants.py`` fails a module-level constant
bound to a number (``NAME = 0.85``) or an upper-case class attribute bound
to one (``<module>:<Class>.<NAME>``) that is not listed here, and an entry
whose constant is gone. A number that tunes what is retrieved, extracted or
answered belongs in the configuration, with an evidence tag
(``domain/models/evidence.py``); list a new constant here only when it is
none of that, and say which reason holds. The ``unmeasured`` entries are
candidates for the experiment plan or for configuration.
"""

from __future__ import annotations

LIMIT = "limit: a bound of the service, file system, format or library it talks to"
UPSTREAM = "upstream: the original library's or paper's value"
FORMAT = "format: a version, digest length, exit code or protocol code"
OPERATIONAL = (
    "operational: batching, paging, timeouts, concurrency, memory or logging; "
    "what is retrieved or answered does not depend on it"
)
CAP = "cap: bounds oversized or untrusted input before it is processed"
PRESENTATION = "presentation: what a CLI, console page, log line or chart shows"
NUMERIC = (
    "numeric: a floating-point, arithmetic or statistical guard (a significance "
    "level, a minimum sample), not a tuning value"
)
UNMEASURED = (
    "unmeasured: shapes what is retrieved, extracted or answered and no run "
    "compared it; a candidate for the experiment plan or configuration"
)
DERIVED = "derived: computed from a measurement or a model property its comment cites"


def _reason(reason: str, *keys: str) -> dict[str, str]:
    return dict.fromkeys(keys, reason)


